pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title TayaqanCertificate
 * @notice Certificate authenticity verification system
 * @dev Minimal, cost-optimized design for MVP
 * 
 * Core Purpose: Prove certificates are authentic and not revoked
 * Storage: Only certificate existence and status (no access control)
 * Access Control: Managed off-chain in database for cost and privacy
 */
contract TayaqanCertificate is Ownable {
    
    // Custom errors (more gas-efficient than require strings)
    error AlreadyIssued();
    error NotFound();
    error AlreadyRevoked();

    struct Certificate {
        bytes32 applicantIdHash;  // Privacy-preserving applicant identifier
        uint64 issuedAt;          // Issuance timestamp (0 = not issued)
        bool revoked;             // Revocation status
    }

    // Primary storage: fileHash → Certificate
    mapping(bytes32 => Certificate) public certByFileHash;

    // Events for audit trail and off-chain indexing
    event CertificateIssued(bytes32 indexed applicantIdHash, bytes32 indexed fileHash, uint64 issuedAt);
    event CertificateRevoked(bytes32 indexed fileHash, uint64 revokedAt);

    constructor(address initialOwner) Ownable(initialOwner) {}

    /**
     * @notice Issue new certificate on blockchain
     * @param applicantIdHash Hash of applicant's national ID
     * @param fileHash Hash of certificate PDF (keccak256)
     * @dev Called by backend when institution uploads certificate
     */
    function issueCertificate(bytes32 applicantIdHash, bytes32 fileHash) external onlyOwner {
        if (certByFileHash[fileHash].issuedAt != 0) revert AlreadyIssued();
        
        certByFileHash[fileHash] = Certificate({
            applicantIdHash: applicantIdHash,
            issuedAt: uint64(block.timestamp),
            revoked: false
        });
        
        emit CertificateIssued(applicantIdHash, fileHash, uint64(block.timestamp));
    }

    /**
     * @notice Revoke certificate (instant global effect)
     * @param fileHash Hash of certificate to revoke
     * @dev Called by backend when institution revokes certificate
     */
    function revokeCertificate(bytes32 fileHash) external onlyOwner {
        Certificate storage c = certByFileHash[fileHash];
        if (c.issuedAt == 0) revert NotFound();
        if (c.revoked) revert AlreadyRevoked();
        
        c.revoked = true;
        emit CertificateRevoked(fileHash, uint64(block.timestamp));
    }

    /**
     * @notice Get certificate details
     * @param fileHash Certificate hash
     * @return applicantIdHash Hash of certificate owner
     * @return issuedAt Unix timestamp of issuance
     * @return revoked Revocation status
     * @dev Used for single certificate detail views
     */
    function getCertificate(bytes32 fileHash)
        external
        view
        returns (bytes32 applicantIdHash, uint64 issuedAt, bool revoked)
    {
        Certificate memory c = certByFileHash[fileHash];
        if (c.issuedAt == 0) revert NotFound();
        return (c.applicantIdHash, c.issuedAt, c.revoked);
    }

    /**
     * @notice Check if certificate is valid (exists and not revoked)
     * @param fileHash Certificate hash
     * @return valid True if certificate exists and is not revoked
     * @dev Used for quick access control checks before file download
     */
    function isCertificateValid(bytes32 fileHash) external view returns (bool valid) {
        Certificate memory c = certByFileHash[fileHash];
        return c.issuedAt > 0 && !c.revoked;
    }

    /**
     * @notice Batch get multiple certificates (gas-efficient)
     * @param fileHashes Array of certificate hashes
     * @return certificates Array of certificate data
     * @dev Primary function for list views - verifies all certificates in one call
     *      Use this for: employer certificate lists, applicant dashboards, institution reports
     */
    function getCertificatesBatch(bytes32[] calldata fileHashes)
        external
        view
        returns (Certificate[] memory certificates)
    {
        certificates = new Certificate[](fileHashes.length);
        for (uint256 i = 0; i < fileHashes.length; i++) {
            certificates[i] = certByFileHash[fileHashes[i]];
        }
    }
}","keccak256":"0x017cbdd4022913f0f078d5d12cb654ed6b32249099e00bd5ef88b7857f29a6b7","license":"UNLICENSED"}},"version":1}
